contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        uint balBefore = address(this).balance;
        uint cBalBefore = address(c).balance;
        uint potBefore = c.pot();
        address bankBefore = c.bank();

        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = address(this).balance;
        uint potAfter = c.pot();

        if (amount != 10) {
            assert(reverted && potAfter == potBefore && balAfter == balBefore);
        } else if (!reverted) {
