            bool lost = (potBefore + amount != 10) && (potAfter == potBefore + amount);
            uint expectedDelta = won ? (potBefore + amount - 1) : 0;
            assert((won && balAfter == balBefore - amount + expectedDelta) || (lost && balAfter == balBefore - amount));
        } else {
            assert(false);
        }
    }

    receive() external payable {}
}

